const el=id=>document.getElementById(id);let locationValue=null,previewURL=null,cursor=null,observationId=null;
function resetTime(){const date=new Date();el('time').value=new Date(date-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}resetTime();
el('photo').onchange=()=>{observationId=null;const file=el('photo').files[0];if(previewURL)URL.revokeObjectURL(previewURL);if(file){previewURL=URL.createObjectURL(file);el('preview').src=previewURL;el('preview').hidden=false}};
el('locate').onclick=()=>{if(!navigator.geolocation){el('location').textContent='Location unavailable. You can still save.';return}el('locate').disabled=true;el('location').textContent='Finding current location…';navigator.geolocation.getCurrentPosition(position=>{const c=position.coords;locationValue={latitude:c.latitude,longitude:c.longitude,accuracy:c.accuracy,capturedAt:new Date(position.timestamp).toISOString()};el('location').textContent=`Current location: ${c.latitude.toFixed(5)}, ${c.longitude.toFixed(5)} · accuracy ±${Math.round(c.accuracy)} m`;el('clear').hidden=false;el('locate').disabled=false},()=>{el('location').textContent='Could not get location. Try again or save without it.';el('locate').disabled=false},{enableHighAccuracy:true,timeout:12000,maximumAge:0})};
el('clear').onclick=()=>{locationValue=null;el('clear').hidden=true;el('location').textContent='No location attached.'};
async function request(url,options){const response=await fetch(url,options);if(!response.ok){let message='Could not access your collection. Please retry.';try{message=(await response.json()).error||message}catch{}throw new Error(message)}return response.json()}
function card(item){const article=document.createElement('article'),img=document.createElement('img'),body=document.createElement('div');img.src='/api/observations/'+item.id+'/photo';img.alt='Unidentified flower observation';img.loading='lazy';const badge=document.createElement('span');badge.className='badge';badge.textContent='UNIDENTIFIED';body.append(badge);for(const text of [new Date(item.observedAt).toLocaleString(),item.location?`${item.location.latitude.toFixed(5)}, ${item.location.longitude.toFixed(5)} · ±${Math.round(item.location.accuracy)} m`:'No location',item.notes]){if(text){const p=document.createElement('p');p.textContent=text;body.append(p)}}const link=document.createElement('a');link.href=img.src;link.target='_blank';link.rel='noopener';link.textContent='Open photo';body.append(link);article.append(img,body);return article}
async function load(append=false){el('refresh').disabled=true;el('more').disabled=true;try{const data=await request('/api/observations'+(append&&cursor?'?cursor='+encodeURIComponent(cursor):''));if(!append)el('list').replaceChildren();for(const item of data.items)el('list').append(card(item));if(!el('list').children.length)el('list').textContent='No discoveries yet. Save your first flower.';cursor=data.cursor;el('more').hidden=!cursor}catch(error){el('status').textContent=error.message}finally{el('refresh').disabled=false;el('more').disabled=false}}
el('form').onsubmit=async event=>{event.preventDefault();const file=el('photo').files[0];if(!file||file.size>10485760){el('status').textContent='Choose a photo smaller than 10 MB.';return}const time=new Date(el('time').value);if(!Number.isFinite(time.getTime()))return;observationId ||= String(9999999999999-Date.now()).padStart(13,'0')+'-'+crypto.randomUUID();const data=new FormData();data.append('photo',file);data.append('metadata',JSON.stringify({id:observationId,observedAt:time.toISOString(),notes:el('notes').value,location:locationValue}));el('save').disabled=true;el('status').textContent='Uploading photo… Keep this page open.';try{await request('/api/observations',{method:'POST',body:data});el('form').reset();resetTime();el('preview').hidden=true;el('clear').click();observationId=null;el('status').textContent='Saved privately. Ready for your next discovery.';await load()}catch(error){el('status').textContent=error.message+' Your photo is still selected.'}finally{el('save').disabled=false}};
el('refresh').onclick=()=>load();el('more').onclick=()=>load(true);load();
